import React, { useMemo, useState } from 'react';
import { motion } from 'framer-motion';
import { Phone, Mail, MessageCircle, Send, Zap } from 'lucide-react';
import './ContactSection.css';
import { postToAppsScript } from '../chatbot/submitForm';

const CONTACT_TYPES = [
  'PLC Panel',
  'VFD Panel',
  'MCC Assembly',
  'BMS Panel',
  'Safety & ESD Panel',
  'Other',
];

const APPS_SCRIPT_URL = 'YOUR_APPS_SCRIPT_URL'; // placeholder (replaced in submitForm.js)

const ContactSection = () => {
  const [form, setForm] = useState({
    name: '',
    email: '',
    phone: '',
    company: '',
    project_type: 'PLC Panel',
    message: '',
  });
  const [errors, setErrors] = useState({});
  const [success, setSuccess] = useState(false);

  const quickContacts = useMemo(
    () => ({
      whatsapp: 'https://wa.me/971504327804', // TODO: replace with real WhatsApp number
      phone: '+971504327804', // TODO: replace with real company phone
      email: 'info@voltronix.ae', // TODO: replace with real company email
    }),
    []
  );

  const validate = () => {
    const nextErrors = {};
    if (!form.name.trim()) nextErrors.name = 'Name is required';
    if (!form.email.trim()) nextErrors.email = 'Email is required';
    if (!form.message.trim()) nextErrors.message = 'Message is required';
    setErrors(nextErrors);
    return Object.keys(nextErrors).length === 0;
  };

  const onChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
    if (errors[name]) {
      setErrors((prev) => {
        const copy = { ...prev };
        delete copy[name];
        return copy;
      });
    }
  };

  const onSubmit = async (e) => {
    e.preventDefault();
    setSuccess(false);

    if (!validate()) return;

    const payload = {
      source: 'form',
      timestamp: new Date().toISOString(),
      name: form.name,
      email: form.email,
      phone: form.phone,
      company: form.company,
      project_type: form.project_type,
      message: form.message,
    };

    // silent fail in util
    await postToAppsScript(payload, APPS_SCRIPT_URL);

    setSuccess(true);
    setForm({
      name: '',
      email: '',
      phone: '',
      company: '',
      project_type: 'PLC Panel',
      message: '',
    });
    setErrors({});
    setTimeout(() => setSuccess(false), 3500);
  };

  const scrollToContact = () => {
    const el = document.getElementById('contact');
    if (el) el.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <section id="contact" className="contact-section">
      <div className="contact-bg">
        <div className="contact-grid" />
        <div className="contact-orb orb-1" />
        <div className="contact-orb orb-2" />
      </div>

      <div className="contact-container">
        <motion.div
          className="section-header"
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
        >
          <div className="section-badge">
            <Zap className="badge-icon" />
            <span>Contact Voltronix Automation</span>
          </div>
          <h2 className="section-title">
            Powering Industry Through <span className="gradient-text">Automation</span>
          </h2>
          <p className="section-subtitle">
            Contact Voltronix Automation today to discuss your industrial control panel and automation requirements.
          </p>
        </motion.div>

        <div className="contact-top">
          <motion.div
            className="contact-cards"
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6 }}
          >
            <div className="contact-card">
              <Phone className="contact-icon" />
              <div className="contact-card-text">
                <h3>Phone</h3>
                <p>{quickContacts.phone}</p>
              </div>
            </div>
            <div className="contact-card">
              <Mail className="contact-icon" />
              <div className="contact-card-text">
                <h3>Email</h3>
                <p>{quickContacts.email}</p>
              </div>
            </div>
            <div className="contact-card">
              <MessageCircle className="contact-icon" />
              <div className="contact-card-text">
                <h3>WhatsApp</h3>
                <p>+971504327804</p>
              </div>
            </div>

            <div className="contact-actions">
              <a
                className="btn-primary contact-whatsapp"
                href={quickContacts.whatsapp}
                target="_blank"
                rel="noreferrer"
              >
                <span>Chat on WhatsApp</span>
              </a>
              <button className="btn-secondary" onClick={scrollToContact} type="button">
                <span>Contact Form</span>
              </button>
            </div>
          </motion.div>

          <motion.div
            className="contact-form-wrap"
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6, delay: 0.1 }}
          >
            <form className="contact-form" onSubmit={onSubmit}>
              <div className="form-row">
              <label>
                Name*{errors.name ? <span className="error-hint">{errors.name}</span> : null}
                <input
                  name="name"
                  value={form.name}
                  onChange={onChange}
                  className={errors.name ? 'invalid' : ''}
                  placeholder="Your name"
                  type="text"
                />
              </label>

                <label>
                  Email*{errors.email ? <span className="error-hint">{errors.email}</span> : null}
                  <input
                    name="email"
                    value={form.email}
                    onChange={onChange}
                    className={errors.email ? 'invalid' : ''}
                    placeholder="your@email.com"
                    type="email"
                  />
                </label>
              </div>

              <div className="form-row">
                <label>
                  Phone
                  <input
                    name="phone"
                    value={form.phone}
                    onChange={onChange}
                    placeholder="+971..."
                    type="tel"
                  />
                </label>
                <label>
                  Company
                  <input
                    name="company"
                    value={form.company}
                    onChange={onChange}
                    placeholder="Company name"
                    type="text"
                  />
                </label>
              </div>

              <div className="form-row">
                <label>
                  Project Type
                  <select name="project_type" value={form.project_type} onChange={onChange}>
                    {CONTACT_TYPES.map((t) => (
                      <option key={t} value={t}>
                        {t}
                      </option>
                    ))}
                  </select>
                </label>
                <div className="form-spacer" />
              </div>

              <label className="message-label">
                Message*{errors.message ? <span className="error-hint">{errors.message}</span> : null}
                <textarea
                  name="message"
                  value={form.message}
                  onChange={onChange}
                  className={errors.message ? 'invalid' : ''}
                  placeholder="Tell us about your panel requirements (PLC, VFD, MCC, BMS, ATS/Generator, timelines, etc.)"
                  rows={5}
                />
              </label>

              <div className="form-footer">
                <button className="btn-primary" type="submit">
                  <Send size={18} />
                  <span>Send Message</span>
                </button>

                {success ? (
                  <div className="form-success">
                    Thank you — we'll be in touch within 2 hours.
                  </div>
                ) : null}
              </div>
            </form>
          </motion.div>
        </div>
      </div>
    </section>
  );
};

export default ContactSection;
